import math

def is_triangular(x):
    """Check if x is a triangular number"""
    if x < 0:
        return False
    discriminant = 1 + 8 * x
    if discriminant < 0:
        return False
    sqrt_d = math.isqrt(discriminant)
    if sqrt_d * sqrt_d != discriminant:
        return False
    k = (-1 + sqrt_d) / 2
    return k.is_integer()

n = int(input())
found = False

# Try all possible values of a
for a in range(1, int(math.isqrt(2 * n)) + 1):
    t_a = a * (a + 1) // 2
    if t_a > n:
        break
    if is_triangular(n - t_a):
        found = True
        break

print("YES" if found else "NO")
"}

