import sys

def solve_rebus(rebus):
    # Parse the input
    parts = rebus.split()

    # Find the result n
    result_index = None
    for i, part in enumerate(parts):
        if part == '=':
            result_index = i
            break

    if result_index is None:
        return "Impossible"

    # Extract the operations and the result
    operations = parts[1:result_index - 1]
    n = int(parts[result_index + 1])
    k = len(operations) + 1  # Number of question marks

    # Try all possible values for each question mark using backtracking
    # We'll try values from 1 to n for each question mark
    # We'll check if the equation holds with the current values

    # This is a brute force approach with pruning
    def backtrack(index, current_value):
        # index: current question mark index (0-indexed)
        # current_value: result so far

        if index == k:
            return current_value == n, [0] * k  # Return success and values

        # Try all possible values for the current question mark
        for value in range(1, n + 1):
            next_value = 0

            # Apply the operation
            if index == 0:
                next_value = value
            elif index == 1:
                next_value = current_value + value
            else:
                # Apply the operation between previous value and current question mark
                if operations[index - 2] == '+':
                    next_value = current_value + value
                else:  # '-'
                    next_value = current_value - value

            # Recursively try the next question mark
            success, values = backtrack(index + 1, next_value)

            if success:
                values[index] = value
                return True, values

        return False, None

    success, values = backtrack(0, 0)

    if success:
        return "Possible" + "\n" + " ".join(str(values[i]) + " " + parts[2 * i + 1] + " " + str(values[i + 1]) for i in range(k - 1)) + " = " + str(n)
    else:
        return "Impossible"

if __name__ == "__main__":
    rebus = sys.stdin.read().strip()
    result = solve_rebus(rebus)
    print(result)
"}

