def is_triangular(n):
    """Check if n is a triangular number"""
    # Solve k*(k+1)/2 = n => k^2 + k - 2n = 0
    # Using quadratic formula: k = [-1 + sqrt(1 + 8n)] / 2
    k = (-1 + (1 + 8 * n) ** 0.5) / 2
    return k.is_integer()

def can_be_sum_of_two_triangular_numbers(n):
    """Check if n can be expressed as sum of two triangular numbers"""
    # Generate all triangular numbers up to n
    triangular_numbers = set()
    k = 0
    while True:
        t = k * (k + 1) // 2
        if t > n:
            break
        triangular_numbers.add(t)
        k += 1

    # Check all pairs
    for t in triangular_numbers:
        if (n - t) in triangular_numbers:
            return True
    return False

n = int(input())
if can_be_sum_of_two_triangular_numbers(n):
    print("YES")
else:
    print("NO")
"}

