def can_be_sum_of_two_triangular_numbers(n):
    """Check if n can be expressed as sum of two triangular numbers"""
    # Generate all triangular numbers up to n
    triangular_numbers = set()
    k = 1  # Start from k=1 to avoid 0
    while True:
        t = k * (k + 1) // 2
        if t > n:
            break
        triangular_numbers.add(t)
        k += 1

    # Check all pairs
    for t in triangular_numbers:
        remainder = n - t
        # Check if remainder is triangular using integer arithmetic
        if remainder < 0:
            continue
        discriminant = 1 + 8 * remainder
        # Check if discriminant is a perfect square
        sqrt_disc = int(discriminant ** 0.5)
        if sqrt_disc * sqrt_disc == discriminant:
            k = (-1 + sqrt_disc) // 2
            if k > 0 and k * (k + 1) // 2 == remainder:
                return True
