    if len(values) == 1:
        if values[0] == target_n:
            return "Possible\n" + rebus.replace('?', str(values[0]))
        return "Impossible"

    # Calculate initial result
    result = values[0]
    for i in range(len(ops)):
        if ops[i] == '+':
            result += values[i + 1]
        else:  # '-'
