    colors = list(map(int, input().split()))
    required = list(map(int, input().split()))

    # Check if total counts meet requirements
    total_counts = [0] * m
    for color in colors:
        total_counts[color - 1] += 1

    for i in range(m):
        if total_counts[i] < required[i]:
            print(-1)
            return

    # Try all possible contiguous intervals
    min_remove = float('inf')

    for left in range(n):
        window_counts = [0] * m

        for right in range(left, n):
            color = colors[right]
            window_counts[color - 1] += 1

            # Check if window meets requirements
            valid = True
            for i in range(m):
                if window_counts[i] < required[i]:
                    valid = False
                    break

            if valid:
                # Calculate minimum removals
                remove = 0
                for i in range(m):
                    if window_counts[i] > required[i]:
                        remove += window_counts[i] - required[i]

                min_remove = min(min_remove, remove)


    print(min_remove)

