    segments.append((l, r))

# Sort segments by their left endpoint
segments.sort()

# Check if consecutive segments form an edge
# And if each segment (except the first) has exactly one neighbor
prev = None
degree = [0] * n

for i in range(n):
    l1, r1 = segments[i]

    # Check if it has a left neighbor
    if i > 0:
        l2, r2 = segments[i - 1]
        if l1 < r2 and l2 < r1:
            if not (l1 >= l2 and r1 <= r2) and not (l2 >= l1 and r2 <= r1):
                degree[i] += 1

    # Check if it has a right neighbor
    if i < n - 1:
        l2, r2 = segments[i + 1]
        if l1 < r2 and l2 < r1:
            if not (l1 >= l2 and r1 <= r2) and not (l2 >= l1 and r2 <= r1):
                degree[i] += 1

# For a tree, each node should have degree 1 (except possibly 2 endpoints)
# In a sorted chain, first and last should have degree 1, others degree 2
# But wait, with n-1 edges between consecutive segments, everyone has degree 2 except endpoints

# Actually, if we have n-1 edges between consecutive segments, the first has 1 neighbor, the last has 1 neighbor, and all middle have 2 neighbors
if degree.count(1) == 2 and degree.count(2) == n - 2:
    print("YES")
else:
    print("NO")
