    y1_set = set(y1)
    y2_set = set(y2)

    # Generate all valid positions for small spaceships (midpoints between pairs of spaceships)
    valid_positions = set()
    for y1_val in y1:
        for y2_val in y2:
            valid_positions.add((y1_val + y2_val) / 2)

    best = 0

    # Try all pairs of valid positions for the two small spaceships
    for y1_pos in valid_positions:
        # Compute which spaceships are destroyed by the first small spaceship
        destroyed1 = set()
        for i, y in enumerate(y1):
            if (2 * y1_pos - y) in y2_set:
                destroyed1.add(i)

        destroyed2 = set()
        for j, y in enumerate(y2):
            if (2 * y1_pos - y) in y1_set:
                destroyed2.add(j)

        # Try placing second small spaceship at each valid position
        for y2_pos in valid_positions:
            destroyed1_2 = set()
            for i, y in enumerate(y1):
                if (2 * y2_pos - y) in y2_set:
                    destroyed1_2.add(i)

            destroyed2_2 = set()
            for j, y in enumerate(y2):
                if (2 * y2_pos - y) in y1_set:
                    destroyed2_2.add(j)

            # Count total destroyed
            total = len(destroyed1 | destroyed1_2) + len(destroyed2 | destroyed2_2)
            best = max(best, total)

    print(best)

