    val = a[i]

    # Check if val-1 exists in the dp
    if val - 1 in dp:
        dp[val] = dp[val - 1] + 1
        # Track the sequence
        sequence_map[val] = sequence_map[val - 1] + [i + 1]  # Store 1-indexed indices
    else:
        dp[val] = 1
        sequence_map[val] = [i + 1]

