import sys

def is_unique(lst):
    """Check if a list has all unique elements"""
    return len(set(lst)) == 9

def solve(grid):
    """Make the grid anti-Sudoku"""
    # Make sure each row has duplicates
    for i in range(9):
        if is_unique(grid[i]):
            # Change last element to match the first
            grid[i][-1] = grid[i][0]

    # Make sure each column has duplicates
    for j in range(9):
        if is_unique([grid[i][j] for i in range(9)]):
            # Change last element to match the first
            grid[-1][j] = grid[0][j]

    # Make sure each block has duplicates
    for block_row in range(3):
        for block_col in range(3):
            # Extract the block
            block = []
            for i in range(block_row * 3, block_row * 3 + 3):
                for j in range(block_col * 3, block_col * 3 + 3):
                    block.append(grid[i][j])

            if is_unique(block):
                # Change last element to match the first
                # Find the position of the last element in the block
                last_pos = -1
                for k in range(len(block) - 1, -1, -1):
                    if block[k] != block[-1]:
                        last_pos = k
                        break

                # Change it to match the first element
                block[last_pos] = block[0]

                # Update the grid
                pos = 0
                for i in range(block_row * 3, block_row * 3 + 3):
                    for j in range(block_col * 3, block_col * 3 + 3):
                        if pos == last_pos:
                            grid[i][j] = block[0]
                        pos += 1

    return grid

def main():
    data = sys.stdin.read().split()
    t = int(data[0])
    idx = 1

    for _ in range(t):
        grid = []
        for _ in range(9):
            row = data[idx:idx+9]
            grid.append(row)
            idx += 9

        result = solve(grid)

        # Print the result
        for row in result:
            print(''.join(row))

if __name__ == "__main__":
    main()
