def solve():
    n = int(sys.stdin.readline())

    # Three stacks: stack, queue, deck (where deck can pop from either end)
    stack = []
    queue = []
    deck = []

    for _ in range(n):
        line = sys.stdin.readline().strip()

        if line == '0':
            # Extract command
            non_empty = []
            if stack:
                non_empty.append(('stack', stack[-1]))
            if queue:
                non_empty.append(('queue', queue[-1]))
            if deck:
                non_empty.append(('deck', deck[-1]))

            if not non_empty:
                print(0)
            else:
                # Sort by the value to extract from the container with the largest number first
                non_empty.sort(key=lambda x: x[1], reverse=True)

                # Extract from all non-empty containers
                result = []
                for container_type, _ in non_empty:
                    if container_type == 'stack':
                        val = stack.pop()
                        result.append('popStack')
                    elif container_type == 'queue':
                        val = queue.pop(0)
                        result.append('popQueue')
                    elif container_type == 'deck':
                        # For deck, we can pop from either end; we'll pop from the end
                        val = deck.pop()
                        result.append('popBack')

                print(len(result), end=' ')
                print(' '.join(result))
        else:
            # Add command
            a = int(line)

            # Choose the container to add to based on the strategy
            # We want to add to the container that will be extracted later

            # Simple strategy: add to the container that currently has the smallest value
            if not stack:
                stack.append(a)
                print('pushStack')
            elif not queue:
                queue.append(a)
                print('pushQueue')
            elif not deck:
                deck.append(a)
                print('pushFront')
            else:
                # If all are non-empty, we need a better strategy
                # Let's use a round-robin approach with some modification

                # Choose the container with the smallest value
                smallest_val = min(stack[-1], queue[-1], deck[-1])

                if stack[-1] == smallest_val:
