import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    segments = []
    idx = 1

    for _ in range(n):
        l = int(data[idx])
        r = int(data[idx + 1])
        segments.append((l, r))
        idx += 2

    # Sort by left endpoint
    segments.sort()

    edges = 0

    for i in range(1, n):
        l1, r1 = segments[i - 1]
        l2, r2 = segments[i]

        # Check if they intersect and neither is fully inside the other
        if l1 < r2 and l2 < r1:
            edges += 1

    if edges == n - 1:
        print("YES")
    else:
        print("NO")

if __name__ == "__main__":
    solve()
