from collections import defaultdict

freq = defaultdict(int)
for color in colors:
    freq[color] += 1

for i in range(m):
    if freq[i+1] < desired[i]:
        print(-1)
        exit()

# Sliding window to find minimum window with at least desired counts
min_len = float('inf')
count = defaultdict(int)
left = 0

for right in range(n):
    color = colors[right]
    count[color] += 1

    # Check if current window meets the criteria
    valid = True
    for i in range(m):
        if count[i+1] < desired[i]:
            valid = False
            break

    if valid:
        # Try to shrink from left
        while left <= right:
            if all(count[i+1] >= desired[i] for i in range(m)):
                min_len = min(min_len, right - left + 1)
                # Try to move left pointer
                count[colors[left]] -= 1
                left += 1
            else:
                break

if min_len != float('inf'):
    print(n - min_len)
else:
    print(-1)
