def solve():
    n, m, k = map(int, input().split())
    grid = []
    for _ in range(n):
        grid.append(list(input().strip()))

    # Find all empty cells
    empty_cells = []
    for i in range(n):
        for j in range(m):
            if grid[i][j] == '.':
                empty_cells.append((i, j))
    s = len(empty_cells)

    # Build adjacency list for empty cells
    adj = [[] for _ in range(s)]
    for idx, (i, j) in enumerate(empty_cells):
        for di, dj in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            ni, nj = i + di, j + dj
            if 0 <= ni < n and 0 <= nj < m and grid[ni][nj] == '.':
                # Find the index of (ni, nj) in empty_cells
                for other_idx, (other_i, other_j) in enumerate(empty_cells):
                    if other_i == ni and other_j == nj:
                        adj[idx].append(other_idx)
                        break

    # Perform BFS to build spanning tree
    visited = [False] * s
    parent = [-1] * s
    queue = []

    # Start from the first empty cell
    start_idx = 0
    queue.append(start_idx)
    visited[start_idx] = True

    while queue:
        u = queue.pop(0)
        for v in adj[u]:
            if not visited[v]:
                visited[v] = True
                parent[v] = u
                queue.append(v)

    # Build the spanning tree
    spanning_tree = [start_idx]
    for v in range(1, s):
        if parent[v] != -1:
            spanning_tree.append(v)

    # Remove k leaves from the spanning tree
    # Leaves are nodes with no children in the spanning tree
    # First, build the tree structure
    tree = [[] for _ in range(s)]
    for v in range(1, s):
        u = parent[v]
        if u != -1:
            tree[u].append(v)

    # Find leaves (nodes with no children)
    leaves = [v for v in range(s) if len(tree[v]) == 0]

    # Remove k leaves
    leaves_to_remove = leaves[:k]

    # Mark those cells as X
    for idx in leaves_to_remove:
        i, j = empty_cells[idx]
        grid[i][j] = 'X'

    # Print the result
    for row in grid:
        print(''.join(row))

solve()
