import math

def is_triangular(x):
    if x < 0:
        return False
    sqrt_val = 1 + 8 * x
    if sqrt_val < 0:
        return False
    s = math.isqrt(sqrt_val)
    if s * s == sqrt_val:
        b = (s - 1) // 2
        return b * (b + 1) // 2 == x
    return False

n = int(input())
# Find max a such that a(a+1)//2 <= n
max_a = int((math.sqrt(2 * n) + 1) // 2)
for a in range(max_a + 1):
    t1 = a * (a + 1) // 2
    rem = n - t1
    if rem < 0:
        break
    if is_triangular(rem):
        print("YES")
        exit()
print("NO")
