def solve():
    s = input().strip()
    k = int(input().strip())

    forbidden = set()
    for _ in range(k):
        pair = input().strip()
        forbidden.add((pair[0], pair[1]))
        forbidden.add((pair[1], pair[0]))

    # dp[last_char] = length of longest valid subsequence ending with last_char
    dp = {}

    # Initialize: for 0 characters, no valid subsequences
    # For each possible last character, we can have a subsequence of length 0
    for c in 'abcdefghijklmnopqrstuvwxyz':
        dp[c] = 0

    # Process each character
    for c in s:
        new_dp = {}

        # Option 1: skip this character
        for last_char in dp:
            new_dp[last_char] = max(new_dp.get(last_char, 0), dp[last_char])

        # Option 2: take this character
        for last_char in dp:
            if (last_char, c) not in forbidden:
                new_dp[c] = max(new_dp.get(c, 0), dp[last_char] + 1)

        dp = new_dp

    # The answer is the length of the original string minus the maximum subsequence length
    max_subsequence_length = max(dp.values())
    print(len(s) - max_subsequence_length)

solve()
