    relations = input().strip()

    # Initialize toffees array with all 1s
    toffees = [1] * n

    # Left to right pass
    for i in range(1, n):
        if relations[i-1] == 'R':
            # Right student has higher marks
            if toffees[i] <= toffees[i-1]:
                toffees[i] = toffees[i-1] + 1
        elif relations[i-1] == '=':
            # Equal marks, ensure same number of toffees
            if toffees[i] != toffees[i-1]:
                toffees[i] = toffees[i-1]

    # Right to left pass
    for i in range(n-2, -1, -1):
        if relations[i] == 'L':
            # Left student has higher marks
            if toffees[i] <= toffees[i+1]:
                toffees[i] = toffees[i+1] + 1
        elif relations[i] == '=':
            # Equal marks, ensure same number of toffees
            if toffees[i] != toffees[i+1]:
                toffees[i] = toffees[i+1]

    print(' '.join(map(str, toffees)))

solve()
