t = int(input())
for _ in range(t):
    n = int(input())
    a, b, c = map(int, input().split())
    s = input().strip()

    # Calculate how many wins we can get
    wins = 0
    alice_hands = []

    # Try to win as much as possible
    for i in range(n):
        if s[i] == 'R':
            # Alice can win by playing P
            if b > 0:
                alice_hands.append('P')
                wins += 1
                b -= 1
            else:
                # No paper left, play what's left
                if a > 0:
                    alice_hands.append('R')
                    a -= 1
                else:
                    alice_hands.append('S')
                    c -= 1
        elif s[i] == 'P':
            # Alice can win by playing S
            if c > 0:
                alice_hands.append('S')
                wins += 1
                c -= 1
            else:
                # No scissors left, play what's left
                if a > 0:
                    alice_hands.append('R')
                    a -= 1
                else:
                    alice_hands.append('P')
                    b -= 1
        else:  # s[i] == 'S'
            # Alice can win by playing R
            if a > 0:
                alice_hands.append('R')
                wins += 1
                a -= 1
            else:
                # No rock left, play what's left
                if b > 0:
                    alice_hands.append('P')
                    b -= 1
                else:
                    alice_hands.append('S')
                    c -= 1

    # Check if we can win
    required_wins = (n + 1) // 2  # Equivalent to ceil(n/2)
    if wins >= required_wins:
        print("YES")
        print(''.join(alice_hands))
    else:
        print("NO")
