def solve():
    x = sys.stdin.readline().strip()
    n = len(x)
    m = 1 << n  # 2^n

    # Create array of pairs (i, x XOR i)
    arr = [(i, i ^ int(x, 2)) for i in range(m)]

    # Count pairs of pairs that form an inversion
    complexity = 0
    for i in range(m):
        for j in range(i + 1, m):
            a1, b1 = arr[i]
            a2, b2 = arr[j]
            if a1 < a2 and b1 > b2:
                complexity += 1

    print(complexity % (10**9 + 7))

if __name__ == "__main__":
