import math

def is_triangular(x):
    """Check if x is a triangular number"""
    if x < 1:
        return False
    # Solve k^2 + k - 2x = 0
    # k = [-1 + sqrt(1 + 8x)] / 2
    discriminant = 1 + 8 * x
    sqrt_d = math.isqrt(discriminant)
    if sqrt_d * sqrt_d != discriminant:
        return False
    k = (-1 + sqrt_d) // 2
    return k * (k + 1) // 2 == x

def can_be_sum_of_two_triangular_numbers(n):
    """Check if n can be expressed as sum of two triangular numbers"""
    max_a = int(math.isqrt(2 * n)) + 1
    for a in range(1, max_a + 1):
        t_a = a * (a + 1) // 2
        if t_a > n:
            break
        if is_triangular(n - t_a):
            return True
    return False

n = int(input())
if can_be_sum_of_two_triangular_numbers(n):
    print("YES")
else:
    print("NO")
"}

