        return False
    # Solve k^2 + k - 2x = 0
    # k = [-1 + sqrt(1 + 8x)] / 2
    sqrt_d = math.sqrt(1 + 8 * x)
    if sqrt_d != int(sqrt_d):
        return False
    k = int((sqrt_d - 1) / 2)
    return k * (k + 1) // 2 == x

# Check if n can be expressed as sum of two triangular numbers
def can_be_sum_of_two_triangular_numbers(n):
    max_a = int(math.sqrt(2 * n)) + 1
    for a in range(1, max_a + 1):
        t_a = a * (a + 1) // 2
        if t_a > n:
            break
        if is_triangular(n - t_a):
            return True
    return False

n = int(input())
if can_be_sum_of_two_triangular_numbers(n):
    print("YES")
else:
    print("NO")

