n, m, k = map(int, input().split())
maze = [list(input().strip()) for _ in range(n)]

# Find all empty cells and build a spanning tree
empty_cells = []
for i in range(n):
    for j in range(m):
        if maze[i][j] == '.':
            empty_cells.append((i, j))

# Build a spanning tree using BFS
from collections import deque
visited = [False] * len(empty_cells)
queue = deque()
queue.append(0)
visited[0] = True
spanning_tree = [False] * len(empty_cells)
spanning_tree[0] = True

# Map from cell position to index in empty_cells list
pos_to_idx = {(i, j): idx for idx, (i, j) in enumerate(empty_cells)}

# Directions: up, down, left, right
directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

while queue:
    current_idx = queue.popleft()
    current_pos = empty_cells[current_idx]

    for dx, dy in directions:
        nx, ny = current_pos[0] + dx, current_pos[1] + dy

        if 0 <= nx < n and 0 <= ny < m and maze[nx][ny] == '.':
            neighbor_pos = (nx, ny)
            neighbor_idx = pos_to_idx.get(neighbor_pos, -1)

            if neighbor_idx != -1 and not visited[neighbor_idx]:
                visited[neighbor_idx] = True
                queue.append(neighbor_idx)
                spanning_tree[neighbor_idx] = True

# Remove k cells that are not in the spanning tree
removed_count = 0
for i in range(n):
    for j in range(m):
        if maze[i][j] == '.' and not spanning_tree[pos_to_idx[(i, j)]]:
            maze[i][j] = 'X'
            removed_count += 1
            if removed_count == k:
                break
    if removed_count == k:
        break

# Print the result
for row in maze:
    print(''.join(row))
