from collections import deque
visited = [False] * m * n
start = (0, 0)
queue = deque([start])
visited[start[0] * m + start[1]] = True

# Map from cell position to index
pos_to_idx = {}
for i in range(n):
    for j in range(m):
        if maze[i][j] == '.':
            pos_to_idx[(i, j)] = i * m + j

