while queue:
    x, y = queue.popleft()

    for dx, dy in directions:
        nx, ny = x + dx, y + dy

        if 0 <= nx < n and 0 <= ny < m and maze[nx][ny] == '.':
            idx = nx * m + ny
            if not visited[idx]:
                visited[idx] = True
                queue.append((nx, ny))

# Find leaf nodes (degree 1)
leaf_nodes = []
for i in range(n):
    for j in range(m):
        if maze[i][j] == '.' and visited[i * m + j]:
            # Check neighbors
            cnt = 0
            for dx, dy in directions:
                nx, ny = i + dx, j + dy
                if 0 <= nx < n and 0 <= ny < m and maze[nx][ny] == '.':
                    if visited[nx * m + ny]:
                        cnt += 1
            if cnt == 1:
                leaf_nodes.append((i, j))

# Remove k leaf nodes
