def solve():
    import sys
    input = sys.stdin.read()
    data = input.split()

    idx = 0
    t = int(data[idx])
    idx += 1

    results = []

    for _ in range(t):
        n = int(data[idx])
        m = int(data[idx + 1])
        idx += 2

        # Count boxes of each power of two
        box_count = {}
        for i in range(m):
            a = int(data[idx])
            idx += 1
            power = a.bit_length() - 1
            if power in box_count:
                box_count[power] += 1
            else:
                box_count[power] = 1

        # Try to fill the bag
        divisions = 0
        current = n

        # Start from the largest power of two less than or equal to n
        power = current.bit_length() - 1
        while power >= 0:
            if power in box_count:
                boxes_available = box_count[power]
                boxes_needed = (1 << power)

                if boxes_available >= boxes_needed:
                    box_count[power] -= boxes_needed
                    if box_count[power] == 0:
                        del box_count[power]
                else:
                    needed = boxes_needed - boxes_available

                    # Find larger boxes and divide them
                    for larger_power in sorted(box_count.keys(), reverse=True):
                        if larger_power <= power:
                            continue

                        boxes_gotten_per_larger = (1 << (larger_power - power))
                        boxes_divide = min(needed // boxes_gotten_per_larger, box_count[larger_power])

                        if boxes_divide > 0:
                            divisions += (larger_power - power) * boxes_divide
                            boxes_gotten = boxes_divide * boxes_gotten_per_larger
                            needed -= boxes_gotten
                            box_count[larger_power] -= boxes_divide
                            if box_count[larger_power] == 0:
                                del box_count[larger_power]

                        if needed <= 0:
                            break

                    if needed > 0:
                        results.append(-1)
                        break

                if current == 0:
                    break
            else:
                results.append(-1)
                break

        if current == 0:
            results.append(divisions)

    sys.stdout.write("\n".join(map(str, results)))

