import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    m = int(next(it))
    colors = [int(next(it)) for _ in range(n)]
    k = [int(next(it)) for _ in range(m)]

    # Check if total counts are sufficient
    total = [0] * m
    for c in colors:
        total[c - 1] += 1

    for i in range(m):
        if total[i] < k[i]:
            print(-1)
            return

    # Find the longest contiguous subarray that matches the desired counts exactly
    max_len = 0
    for start in range(n):
        cnt = [0] * m
        for end in range(start, n):
            idx = colors[end] - 1
            cnt[idx] += 1
            # Check if we have at least the required counts
            if all(cnt[i] >= k[i] for i in range(m)):
                # Check if we have exactly the required counts
                if all(cnt[i] == k[i] for i in range(m)):
                    max_len = max(max_len, end - start + 1)
                    break  # We can't get longer by extending this window

    if max_len > 0:
        print(n - max_len)
    else:
        print(-1)

if __name__ == "__main__":
    solve()
