q = int(input())
queries = []

for _ in range(q):
    l, r = map(int, input().split())
    queries.append((l, r))

# Build segment tree where each node stores:
# - xor_values: all XOR values of subsegments within this range
# - start_values: XOR values of subsegments starting at the leftmost element
# - end_values: XOR values of subsegments ending at the rightmost element
class SegmentTree:
    def __init__(self, data):
        self.n = len(data)
        self.size = 1
        while self.size < self.n:
            self.size <<= 1
        self.tree = []
        for _ in range(2 * self.size):
            self.tree.append({})  # Dictionary mapping XOR values to start/end indices

        # Fill leaves
        for i in range(self.n):
            self.tree[self.size + i][data[i]] = (i + 1, i + 1)  # (start, end)

        # Build the tree
        for i in range(self.size - 1, 0, -1):
            left = 2 * i
            right = 2 * i + 1

            # Combine left and right
            self.tree[i] = self.tree[left]
            for xor_val, (l_start, l_end) in self.tree[right].items():
                for r_start, r_end in self.tree[left].items():
                    self.tree[i][xor_val ^ r_start] = (l_start, r_end)

    def query(self, l, r):
        # Query range [l, r] (1-indexed)
        l += self.size - 1
        r += self.size - 1
        res = {}
        while l <= r:
            if l % 2 == 1:
                # Add all XOR values in this leaf
                for xor_val, (start, end) in self.tree[l].items():
                    res[xor_val] = (start, end)
                l += 1
            if r % 2 == 0:
                # Add all XOR values in this leaf
                for xor_val, (start, end) in self.tree[r].items():
                    res[xor_val] = (start, end)
                r -= 1
            l //= 2
            r //= 2
        return res

# Build the segment tree
st = SegmentTree(a)

# Process queries
for l, r in queries:
    xor_dict = st.query(l, r)
    max_xor = max(xor_dict.keys())
    print(max_xor)
