import sys

def is_unique(row):
    """Check if a row has all unique elements"""
    return len(set(row)) == 9

def solve_sudoku(grid):
    """Make the grid anti-Sudoku by changing at most 9 elements"""
    # Make sure we don't exceed 9 changes
    changes = 0

    # Process rows
    for i in range(9):
        if changes >= 9:
            break
        row = grid[i]
        if is_unique(row):
            # Change the last element to match the first
            grid[i] = row[:8] + row[0]
            changes += 1

    # Process columns
    for j in range(9):
        if changes >= 9:
            break
        # Extract column
        col = ''.join([grid[i][j] for i in range(9)])
        if is_unique(col):
            # Change the last element to match the first
            # Find which row to change
            for i in range(9):
                if changes >= 9:
                    break
                if is_unique(col):
                    # Change grid[i][j] to match col[0]
                    grid[i] = grid[i][:j] + col[0] + grid[i][j+1:]
                    changes += 1
                    break

    return grid

def main():
    data = sys.stdin.read().split()
    if not data:
        return

    t = int(data[0])
    index = 1

    for _ in range(t):
        grid = []
        for _ in range(9):
            grid.append(data[index])
            index += 1

        solve_sudoku(grid)

        for row in grid:
            sys.stdout.write(row + '\n')
        sys.stdout.write('\n')

if __name__ == "__main__":
    main()
"}

