import sys

def is_unique(s):
    """Check if a string has all unique elements"""
    return len(set(s)) == 9

def solve(grid):
    """Make the grid anti-Sudoku"""
    # Process rows
    for i in range(9):
        if is_unique(grid[i]):
            # Change last element to match first
            grid[i] = grid[i][:8] + grid[i][0]

    # Process columns
    for j in range(9):
        col = ''.join([grid[i][j] for i in range(9)])
        if is_unique(col):
            # Change the last element of the first row that needs it
            for i in range(9):
                if is_unique(col):
                    grid[i] = grid[i][:j] + col[0] + grid[i][j+1:]
                    break

    # Process blocks
    for block_row in range(3):
        for block_col in range(3):
            start_row = block_row * 3
            start_col = block_col * 3
            block = ''.join(grid[i][start_col:start_col+3] for i in range(start_row, start_row+3))
            if is_unique(block):
                # Change the last element of the first row that needs it
                for i in range(start_row, start_row+3):
                    if is_unique(block):
                        grid[i] = grid[i][:start_col] + block[0] + grid[i][start_col+1:]
                        break

    return grid

