        if chosen == 0:
            print("pushStack")
        elif chosen == 1:
            print("pushQueue")
        else:
            print("pushFront")

        # Add to the chosen container
        containers[chosen] += 1
    else:
        # Extract command: extract from containers with most elements
        # Get counts with indices
        counts_with_indices = [(containers[i], i) for i in range(3)]

        # Sort by count (descending) and then by index (ascending)
        counts_with_indices.sort(key=lambda x: (-x[0], x[1]))

        # Extract from top 3 distinct containers
        extracted = []
        for i in range(3):
            if counts_with_indices[i][0] > 0:
                extracted.append(counts_with_indices[i])
