def parse_time(s):
    h, m, s = map(int, s.split(':'))
    return h * 3600 + m * 60 + s


def solve():
    n, M, T = map(int, input().split())
    queries = []
    for _ in range(n):
        t = parse_time(input().strip())
        queries.append(t)

    # Sort queries by time
    queries.sort()

    # Greedily assign users
    user_ids = []
    current_users = {}

    for i in range(n):
        # Try to assign a new user
        new_user = len(current_users) + 1
        intervals = [(queries[i], queries[i] + T - 1)]

        # Check if this new user would cause more than M users online at any point
        # (We need to check overlaps with existing users)
        conflict = False
        for u in current_users:
            for (s1, e1) in current_users[u]:
                for (s2, e2) in intervals:
                    if max(s1, s2) < min(e1, e2):
                        # Overlap found
                        conflict = True
                        break
                if conflict:
                    break
            if conflict:
                break

        if not conflict:
            # No conflict, add as a new user
            current_users[new_user] = intervals
            user_ids.append(new_user)
        else:
            # Conflict, need to merge with previous user
            if i > 0:
                # Merge with previous user
                prev_user = user_ids[-1]
                intervals = current_users[prev_user] + intervals
                del current_users[prev_user]
                current_users[new_user] = intervals
                user_ids[-1] = new_user
            else:
                # No previous user, can't merge (only one query)
                print("No solution")
                return

    # Check if we've reached M users
    if len(current_users) < M:
        print("No solution")
        return

    print(len(current_users))
    for uid in user_ids:
        print(uid)

solve()
