        if cmd == 0:
            # Extract from all containers with elements
            result = []

            # Extract from stack (pop from end)
            if stack:
                result.append(f"popStack")
                val = stack.pop()

            # Extract from queue (pop from front)
            if queue:
                result.append(f"popQueue")
                val = queue.popleft()

            # Extract from deck (choose front or back to maximize sum)
            if deck:
                if not result:
                    # Only one container has elements, extract from deck
                    result.append(f"popFront")
                else:
                    # Choose the extraction point that maximizes the sum
                    if deck[0] > deck[-1]:
                        result.append(f"popFront")
                        val = deck.popleft()
                    else:
                        result.append(f"popBack")
                        val = deck.pop()

