    # Process each character
    for i in range(n):
        next_dp = {chr(c): float('inf') for c in range(ord('a'), ord('z') + 1)}

        # Try removing the current character
        for last_char in dp:
            if dp[last_char] < next_dp[last_char]:
                next_dp[last_char] = dp[last_char]

        # Try keeping the current character
        current_char = s[i]
        for last_char in dp:
            # Option 1: current_char doesn't form a forbidden pair with last_char
