from collections import deque

def solve():
    n, m, k = map(int, input().split())
    grid = []
    for i in range(n):
        grid.append(list(input()))

    # Find all empty cells and pick a starting point
    start = None
    empty_cells = []
    for i in range(n):
        for j in range(m):
            if grid[i][j] == '.':
                empty_cells.append((i, j))
                if start is None:
                    start = (i, j)

    # BFS to find connected component of size (s - k)
    visited = set()
    queue = deque([start])
    visited.add(start)

    # Stop when we've visited exactly (s - k) cells
    while queue and len(visited) < len(empty_cells) - k:
        x, y = queue.popleft()
        for dx, dy in [(-1,0),(1,0),(0,-1),(0,1)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < m:
                if grid[nx][ny] == '.' and (nx, ny) not in visited:
                    visited.add((nx, ny))
                    queue.append((nx, ny))

    # Mark unvisited empty cells as walls
    for i in range(n):
        for j in range(m):
            if grid[i][j] == '.' and (i, j) not in visited:
                grid[i][j] = 'X'

    for row in grid:
        print(''.join(row))

solve()
